import styled, { css } from 'styled-components';

import { COLOR, TRANSPARENT, TYPOGRAPHY } from '../../foundation';

import type { AdVariant } from './Ad.types';

const bannerStyle = css`
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 12px;
`;

const cardStyle = css`
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  overflow: hidden;
  border-radius: 12px;
  box-shadow: inset 0 0 0 1px ${TRANSPARENT.GRAY[200]};
  color: inherit;
  text-decoration: none;
`;

export const Ad = styled.div<{ $variant: AdVariant }>`
  box-sizing: border-box;
  width: 100%;
  color: ${COLOR.BLACK};
  background-color: ${COLOR.WHITE};
  word-break: break-word;

  ${({ $variant }) => {
    switch ($variant) {
      case 'banner-small':
        return css`
          ${bannerStyle}
          height: 56px;
        `;
      case 'banner-large':
        return css`
          ${bannerStyle}
          height: 80px;
        `;
      case 'banner-landing':
        return css`
          ${bannerStyle}
          height: 50px;
          border-radius: 0;
        `;
      case 'card-large':
        return css`
          ${cardStyle}
          width: 340px;
          height: 200px;
        `;
      case 'card-medium':
        return css`
          ${cardStyle}
          width: 298px;
          height: 170px;
        `;
      case 'card-small':
        return css`
          ${cardStyle}
          height: 160px;
        `;
    }
  }}
`;

export const Track = styled.div`
  display: flex;
  width: 100%;
  height: 100%;
  transition: transform 200ms ease;
`;

export const CardCarouselNav = styled.div`
  position: absolute;
  right: 8px;
  bottom: 8px;
  z-index: 2;
  display: flex;
  align-items: center;
  padding: 2px 3px;
  border-radius: 20px;
  background: rgba(0, 0, 0, 0.4);
`;

export const CardArrowButton = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
`;

export const IndicatorGroup = styled.div<{ $variant: AdVariant }>`
  position: absolute;
  bottom: 0;
  left: 50%;
  z-index: 3;
  display: flex;
  gap: 5px;
  align-items: center;
  transform: translateX(-50%);
`;

export const IndicatorButton = styled.button<{
  $active: boolean;
  $color: string;
  $variant: AdVariant;
}>`
  position: relative;
  width: ${({ $active }) => ($active ? '24px' : '8px')};
  height: ${({ $variant }) => ($variant === 'banner-large' ? '32px' : '28px')};
  padding: 0;
  color: ${({ $color }) => $color};
  border: 0;
  background: transparent;
  cursor: pointer;

  &::before {
    position: absolute;
    bottom: ${({ $variant }) => ($variant === 'banner-large' ? '8px' : '4px')};
    left: 50%;
    width: ${({ $active }) => ($active ? '24px' : '8px')};
    height: 4px;
    opacity: ${({ $active }) => ($active ? 0.8 : 0.4)};
    border-radius: 2px;
    background-color: currentColor;
    content: '';
    transform: translateX(-50%);
    transition: width 200ms ease, opacity 200ms ease;
  }
`;

export const CloseButton = styled.button`
  position: absolute;
  top: 50%;
  right: 16px;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  transform: translateY(-50%);
  border: 0;
  background: transparent;
  cursor: pointer;
`;

export const Slide = styled.div<{
  $backgroundColor?: string;
  $textColor?: string;
  $variant: AdVariant;
}>`
  position: relative;
  display: flex;
  flex: 0 0 100%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  overflow: hidden;
  color: ${({ $textColor }) => $textColor || '#333333'};
  background-color: ${({ $backgroundColor }) => $backgroundColor || '#ffffff'};
  text-decoration: none;

  ${({ $variant }) =>
    $variant === 'banner-landing' &&
    css`
      border-radius: 0;
    `}

  ${({ $variant }) =>
    $variant.startsWith('card') &&
    css`
      align-items: flex-start;
      padding: 0;
    `}
`;

export const Content = styled.div<{ $variant: AdVariant }>`
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  padding: 13px 16px;

  ${({ $variant }) =>
    $variant.startsWith('banner') &&
    css`
      width: 550px;
      text-align: center;
    `}

  ${({ $variant }) =>
    $variant === 'banner-small' &&
    css`
      justify-content: flex-start;
      padding: 8px 16px;
    `}

  ${({ $variant }) =>
    $variant.startsWith('card') &&
    css`
      padding: ${$variant === 'card-small' ? '16px' : '20px'};
      text-align: left;
      white-space: nowrap;
      justify-content: flex-start;
    `}
`;

export const Title = styled.p<{ $variant: AdVariant }>`
  position: relative;
  z-index: 1;
  margin: 0;
  font-weight: 600;
  line-height: 1.5;

  ${({ $variant }) => {
    switch ($variant) {
      case 'banner-small':
        return 'font-size: 14px;';
      case 'banner-large':
      case 'banner-landing':
        return 'font-size: 16px;';
      default:
        return 'font-size: 20px;';
    }
  }}
`;

export const Body = styled.div<{ $variant: AdVariant }>`
  position: relative;
  z-index: 1;
  margin: 0;
  ${TYPOGRAPHY['body-01']}

  ${({ $variant }) =>
    $variant.startsWith('banner') &&
    css`
      font-size: 12px;
    `}

  ${({ $variant }) =>
    $variant === 'banner-small' &&
    css`
      margin-top: -2px;
    `}

  ${({ $variant }) =>
    $variant.startsWith('card') &&
    css`
      font-size: 14px;
      line-height: 1.5;
    `}
`;

export const Image = styled.img<{ $variant: AdVariant }>`
  position: absolute;
  top: 0;
  left: 50%;
  z-index: 0;
  width: auto;
  max-width: none;
  height: 100%;
  transform: translateX(-50%);

  ${({ $variant }) =>
    $variant.startsWith('card') &&
    css`
      left: 0;
      width: 100%;
      object-fit: cover;
      transform: none;
    `}
`;

