import { useRouter } from 'next/router';

import { render, screen } from '@testing-library/react';
import { act } from 'react-dom/test-utils';

import Ad from './Ad';
import { sendAdTrackingEvent } from './adTracking';
import { getImageIndicatorColor } from './getAdIndicatorColor';
import { useStrapiCatalog } from './useStrapiCatalog';

jest.mock('../Icon', () => ({
  Icon: ({ color, name }: { color?: string; name: string }) => (
    <span data-color={color} data-testid={`icon-${name}`} />
  ),
}));

jest.mock('../Tooltip', () => ({
  Tooltip: ({ children, label }: React.PropsWithChildren<{ label: string }>) => (
    <span data-tooltip-label={label}>{children}</span>
  ),
}));

jest.mock('./useStrapiCatalog');

jest.mock('next/router', () => ({
  useRouter: jest.fn(),
}));

jest.mock('./adTracking', () => ({
  sendAdTrackingEvent: jest.fn(() => true),
}));

jest.mock('./getAdIndicatorColor', () => ({
  ...jest.requireActual('./getAdIndicatorColor'),
  getImageIndicatorColor: jest.fn(),
}));

const mockedUseStrapiCatalog = jest.mocked(useStrapiCatalog);
const mockedUseRouter = jest.mocked(useRouter);
const mockedSendAdTrackingEvent = jest.mocked(sendAdTrackingEvent);
const mockedGetImageIndicatorColor = jest.mocked(getImageIndicatorColor);

describe('Ad', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.clearAllMocks();
    mockedGetImageIndicatorColor.mockResolvedValue('#333333');
    mockedUseRouter.mockReturnValue({ query: { storeName: 'sixshoptest01' } } as never);
    window.localStorage.clear();
  });

  afterEach(() => {
    jest.restoreAllMocks();
    jest.useRealTimers();
  });

  it('loads Catalog slides when slug is provided', () => {
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ title: 'Catalog title', body: 'Catalog body' }],
    } as never);

    render(<Ad slug='catalog-slug' variant='banner-large' />);

    expect(screen.getByText('Catalog title')).toBeTruthy();
    expect(screen.getByText('Catalog body')).toBeTruthy();
    expect(mockedUseStrapiCatalog).toHaveBeenCalledWith('catalog-slug');
  });

  it('tracks each Catalog creative impression once after the route store identity is ready', () => {
    mockedUseRouter.mockReturnValue({ query: {} } as never);
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ id: 3151, title: 'Catalog title' }],
    } as never);

    const { rerender } = render(<Ad slug='catalog-slug' variant='banner-small' />);

    expect(mockedSendAdTrackingEvent).not.toHaveBeenCalled();

    mockedUseRouter.mockReturnValue({ query: { storeName: 'sixshoptest01' } } as never);
    rerender(<Ad slug='catalog-slug' variant='banner-small' />);
    rerender(<Ad slug='catalog-slug' variant='banner-small' />);

    expect(mockedSendAdTrackingEvent).toHaveBeenCalledTimes(1);
    expect(mockedSendAdTrackingEvent).toHaveBeenCalledWith({
      event: 'catalog-slug',
      user: 'sixshoptest01',
      value: 'Catalog title',
    });
  });

  it('tracks the same Catalog creative again when the store identity changes', () => {
    mockedUseRouter.mockReturnValue({ query: { storeName: 'first-store' } } as never);
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ id: 3151, title: 'Catalog title' }],
    } as never);

    const { rerender } = render(<Ad slug='catalog-slug' variant='banner-small' />);

    mockedUseRouter.mockReturnValue({ query: { storeName: 'second-store' } } as never);
    rerender(<Ad slug='catalog-slug' variant='banner-small' />);

    expect(
      mockedSendAdTrackingEvent.mock.calls.filter(([event]) => event.event === 'catalog-slug')
    ).toEqual([
      [expect.objectContaining({ user: 'first-store' })],
      [expect.objectContaining({ user: 'second-store' })],
    ]);
  });

  it('tracks linked Catalog slide clicks but not indicator clicks', () => {
    window.localStorage.setItem(
      'user',
      JSON.stringify({ currentStore: { storeName: 'sixshoptest01' } })
