import styled, { css } from 'styled-components';

import { COLOR, TRANSPARENT, TYPOGRAPHY } from '../../foundation';

import type { AdVariant } from './Ad.types';

const bannerStyle = css`
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 12px;
`;

const cardStyle = css`
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  overflow: hidden;
  border-radius: 12px;
  box-shadow: inset 0 0 0 1px ${TRANSPARENT.GRAY[200]};
  color: inherit;
  text-decoration: none;
`;

export const Ad = styled.div<{ $variant: AdVariant }>`
  box-sizing: border-box;
  width: 100%;
  color: ${COLOR.BLACK};
  background-color: ${COLOR.WHITE};
  word-break: break-word;

  ${({ $variant }) => {
    switch ($variant) {
      case 'banner-small':
        return css`
          ${bannerStyle}
          height: 56px;
        `;
      case 'banner-large':
        return css`
          ${bannerStyle}
          height: 80px;
        `;
      case 'banner-landing':
        return css`
          ${bannerStyle}
          height: 50px;
          border-radius: 0;
        `;
      case 'card-large':
        return css`
          ${cardStyle}
          width: 340px;
          height: 200px;
        `;
      case 'card-medium':
        return css`
          ${cardStyle}
          width: 298px;
          height: 170px;
        `;
      case 'card-small':
        return css`
          ${cardStyle}
          height: 160px;
        `;
    }
  }}
`;

export const Track = styled.div`
