`;

export const Body = styled.div<{ $variant: AdVariant }>`
  position: relative;
  z-index: 1;
  margin: 0;
  ${TYPOGRAPHY['body-01']}

  ${({ $variant }) =>
    $variant.startsWith('banner') &&
    css`
      font-size: 12px;
