  ${({ $variant }) =>
    $variant.startsWith('card') &&
    css`
      font-size: 14px;
      line-height: 1.5;
    `}
`;

export const Image = styled.img<{ $variant: AdVariant }>`
  position: absolute;
  top: 0;
  left: 50%;
  z-index: 0;
  width: auto;
  max-width: none;
  height: 100%;
  transform: translateX(-50%);

  ${({ $variant }) =>
    $variant.startsWith('card') &&
    css`
      left: 0;
      width: 100%;
      object-fit: cover;
      transform: none;
    `}
`;

