import { useRouter } from 'next/router';

import { useCallback, useEffect, useRef, useState } from 'react';

import { LocalStorage } from '@sixshop3-fe/shared/utils';

import { Icon } from '../Icon';
import { Tooltip } from '../Tooltip';

import * as S from './Ad.styled';
import {
  dismissAdItemForToday,
  getNextAdDismissalExpiry,
  getSafeAdDismissalDelay,
  readDismissedAdItemIds,
} from './adDismissal';
import { sendAdTrackingEvent } from './adTracking';
import { getImageIndicatorColor, getIndicatorColorFromCssColor } from './getAdIndicatorColor';
import { useStrapiCatalog } from './useStrapiCatalog';

import type { AdProps } from './Ad.types';

const INDICATOR_BAR_HEIGHT = 4;

const Ad = ({ className, dismissible, items = [], onVisibilityChange, slug, variant }: AdProps) => {
  const { query } = useRouter();
  const [activeIndex, setActiveIndex] = useState(0);
  const [dismissalState, setDismissalState] = useState<{
    dismissedItemIds: Set<string>;
    slug?: string;
  }>({ dismissedItemIds: new Set() });
  const [closeButtonColor, setCloseButtonColor] = useState('#333333');
  const [indicatorColor, setIndicatorColor] = useState('#333333');
  const [layoutVersion, setLayoutVersion] = useState(0);
  const adRef = useRef<HTMLDivElement>(null);
  const activeIndexRef = useRef(0);
  const closeButtonRef = useRef<HTMLButtonElement>(null);
  const closeButtonRequestRef = useRef(0);
  const indicatorColorCacheRef = useRef(new Map<string, Promise<string>>());
  const indicatorGroupRef = useRef<HTMLDivElement>(null);
  const indicatorRequestRef = useRef(0);
  const rollingGenerationRef = useRef(0);
  const rollingTimerRef = useRef<ReturnType<typeof setTimeout>>();
  const resumeTimerRef = useRef<ReturnType<typeof setTimeout>>();
  const catalog = useStrapiCatalog(slug);
  const resolvedItems = slug ? catalog.items : items;
  const isTodayDismissible = Boolean(dismissible && slug);
  const isDismissalReady = !isTodayDismissible || dismissalState.slug === slug;
  const visibleItems = isTodayDismissible
    ? resolvedItems.filter(
        (item) => item.id === undefined || !dismissalState.dismissedItemIds.has(String(item.id))
      )
    : resolvedItems;
  const isSlider =
    variant === 'banner-small' ||
    variant === 'banner-large' ||
    variant === 'banner-landing' ||
    variant === 'card-large' ||
    variant === 'card-medium' ||
    variant === 'card-small';
  const hasControls = isDismissalReady && isSlider && visibleItems.length > 1;
  const hasBannerIndicators = hasControls && variant.startsWith('banner');
  const hasTodayDismissButton =
    isDismissalReady &&
    isTodayDismissible &&
    visibleItems[activeIndex]?.id !== undefined &&
    variant.startsWith('banner');
  const isVisible =
    !(slug && (catalog.isLoading || catalog.isError)) &&
    isDismissalReady &&
    visibleItems.length > 0;
  const activeItem = visibleItems[activeIndex];
  const activeBackgroundColor = activeItem?.backgroundColor;
  const activeImageSrc = activeItem?.image?.src;
  const controlColor = activeItem?.textColor || '#333333';
  const indicatorBottomOffset = variant === 'banner-large' ? 8 : 4;
  const storeName = typeof query.storeName === 'string' ? query.storeName : undefined;
  // MEMO: 에디터 라우트(/editor/[storeId])에는 storeName 쿼리가 없어 그 구좌의 클릭이 전송되지 않았다.
  // gtmService와 같은 방식으로 로그인 사용자의 현재 스토어로 보완한다.
  const signedInStoreName = LocalStorage.getItem<{ currentStore?: { storeName?: string } }>('user')
    ?.currentStore?.storeName;
  const trackingUser = storeName || signedInStoreName || '';

  const trackCatalogEvent = useCallback(
    (value: string) =>
      slug && trackingUser
        ? sendAdTrackingEvent({
            event: `ad:click:${slug}`,
            user: trackingUser,
            value,
          })
        : false,
    [slug, trackingUser]
  );

  useEffect(() => {
    onVisibilityChange?.(isVisible);
  }, [isVisible, onVisibilityChange]);

  useEffect(() => {
    if (!isTodayDismissible) {
      setActiveIndex(0);
      activeIndexRef.current = 0;
      return;
    }

    if (visibleItems.length === 0 || activeIndexRef.current < visibleItems.length) {
      return;
    }

    const nextIndex = visibleItems.length - 1;
    activeIndexRef.current = nextIndex;
    setActiveIndex(nextIndex);
  }, [isTodayDismissible, slug, visibleItems.length]);

  useEffect(() => {
    if (!isTodayDismissible || !slug) {
      setDismissalState({ dismissedItemIds: new Set() });
      return;
    }

    setDismissalState({
      dismissedItemIds: new Set(readDismissedAdItemIds(window.localStorage, slug, new Date())),
      slug,
    });
  }, [isTodayDismissible, slug]);

  useEffect(() => {
    if (!isTodayDismissible || !slug || dismissalState.slug !== slug) {
      return undefined;
    }

    const now = new Date();
    const nextExpiry = getNextAdDismissalExpiry(window.localStorage, slug, now);

    if (nextExpiry === undefined) {
      return undefined;
    }

    const expiryTimer = setTimeout(() => {
      setDismissalState({
        dismissedItemIds: new Set(readDismissedAdItemIds(window.localStorage, slug, new Date())),
        slug,
      });
    }, getSafeAdDismissalDelay(nextExpiry, now));

    return () => clearTimeout(expiryTimer);
  }, [dismissalState.dismissedItemIds, dismissalState.slug, isTodayDismissible, slug]);

  const moveTo = useCallback(
    (index: number) => {
      if (visibleItems.length === 0) {
        return;
      }

      const nextIndex = (index + visibleItems.length) % visibleItems.length;
      activeIndexRef.current = nextIndex;
      setActiveIndex(nextIndex);
    },
    [visibleItems.length]
  );

  const startRolling = useCallback(() => {
    const generation = rollingGenerationRef.current + 1;
    rollingGenerationRef.current = generation;
    clearTimeout(rollingTimerRef.current);
    rollingTimerRef.current = setTimeout(() => {
      if (rollingGenerationRef.current !== generation) {
        return;
      }

      moveTo(activeIndexRef.current + 1);
      startRolling();
    }, 3000);
  }, [moveTo]);

  useEffect(() => {
    if (!hasControls) {
      clearTimeout(resumeTimerRef.current);
      return undefined;
    }

    startRolling();

    return () => {
      rollingGenerationRef.current += 1;
      clearTimeout(rollingTimerRef.current);
      clearTimeout(resumeTimerRef.current);
    };
  }, [hasControls, startRolling]);

  useEffect(
    () => () => {
      rollingGenerationRef.current += 1;
      clearTimeout(rollingTimerRef.current);
      clearTimeout(resumeTimerRef.current);
    },
    []
  );

  useEffect(() => {
    if (
      (!hasBannerIndicators && !hasTodayDismissButton) ||
      !adRef.current ||
      typeof ResizeObserver === 'undefined'
    ) {
      return undefined;
    }

    const resizeObserver = new ResizeObserver(() => setLayoutVersion((version) => version + 1));
    resizeObserver.observe(adRef.current);

    return () => resizeObserver.disconnect();
  }, [hasBannerIndicators, hasTodayDismissButton]);

  useEffect(() => {
    const requestId = indicatorRequestRef.current + 1;
    indicatorRequestRef.current = requestId;
    setIndicatorColor(controlColor);

    if (!hasBannerIndicators) {
      return;
    }

    if (!activeImageSrc) {
      setIndicatorColor(
        getIndicatorColorFromCssColor(
          activeBackgroundColor || '#ffffff',
          controlColor,
          variant === 'banner-small' ? 0.1 : 0
        )
      );
      return;
    }

    const adRect = adRef.current?.getBoundingClientRect();
    const indicatorRect = indicatorGroupRef.current?.getBoundingClientRect();

    if (!adRect || !indicatorRect) {
      return;
    }

    const imageIndicatorColorParams = {
      backgroundColor: activeBackgroundColor,
      containerHeight: adRect.height,
      containerWidth: adRect.width,
      indicatorHeight: INDICATOR_BAR_HEIGHT,
      indicatorLeft: indicatorRect.left - adRect.left,
      indicatorTop: Math.max(
        0,
        indicatorRect.bottom - adRect.top - indicatorBottomOffset - INDICATOR_BAR_HEIGHT
      ),
      indicatorWidth: indicatorRect.width,
      overlayOpacity: variant === 'banner-small' ? 0.1 : 0,
      src: activeImageSrc,
    };
    const cacheKey = JSON.stringify(imageIndicatorColorParams);
    const cachedColorRequest = indicatorColorCacheRef.current.get(cacheKey);
    const colorRequest = cachedColorRequest || getImageIndicatorColor(imageIndicatorColorParams);

    if (!cachedColorRequest) {
      indicatorColorCacheRef.current.set(cacheKey, colorRequest);
    }

    let cancelled = false;

    void colorRequest
      .then((color) => {
        if (!cancelled && indicatorRequestRef.current === requestId) {
          setIndicatorColor(color);
        }
      })
      .catch(() => indicatorColorCacheRef.current.delete(cacheKey));

    return () => {
      cancelled = true;
    };
  }, [
    activeBackgroundColor,
    activeImageSrc,
    controlColor,
    hasBannerIndicators,
    indicatorBottomOffset,
    layoutVersion,
    variant,
  ]);

  useEffect(() => {
    const requestId = closeButtonRequestRef.current + 1;
    closeButtonRequestRef.current = requestId;
    setCloseButtonColor(controlColor);

    if (!hasTodayDismissButton) {
      return;
    }

    if (!activeImageSrc) {
      setCloseButtonColor(
        getIndicatorColorFromCssColor(
          activeBackgroundColor || '#ffffff',
          controlColor,
          variant === 'banner-small' ? 0.1 : 0
        )
      );
      return;
    }

    const adRect = adRef.current?.getBoundingClientRect();
    const closeButtonRect = closeButtonRef.current?.getBoundingClientRect();

    if (!adRect || !closeButtonRect) {
      return;
    }

    const imageColorParams = {
      backgroundColor: activeBackgroundColor,
      containerHeight: adRect.height,
      containerWidth: adRect.width,
      indicatorHeight: closeButtonRect.height,
      indicatorLeft: closeButtonRect.left - adRect.left,
      indicatorTop: closeButtonRect.top - adRect.top,
      indicatorWidth: closeButtonRect.width,
      overlayOpacity: variant === 'banner-small' ? 0.1 : 0,
      src: activeImageSrc,
    };
    const cacheKey = JSON.stringify(imageColorParams);
    const cachedColorRequest = indicatorColorCacheRef.current.get(cacheKey);
    const colorRequest = cachedColorRequest || getImageIndicatorColor(imageColorParams);

    if (!cachedColorRequest) {
      indicatorColorCacheRef.current.set(cacheKey, colorRequest);
    }

    let cancelled = false;

    void colorRequest
      .then((color) => {
        if (!cancelled && closeButtonRequestRef.current === requestId) {
          setCloseButtonColor(color);
        }
      })
      .catch(() => indicatorColorCacheRef.current.delete(cacheKey));

    return () => {
      cancelled = true;
    };
  }, [
    activeBackgroundColor,
    activeImageSrc,
    controlColor,
    hasTodayDismissButton,
    layoutVersion,
    variant,
  ]);

  const handleManualMove = (index: number) => {
    moveTo(index);
    rollingGenerationRef.current += 1;
    const generation = rollingGenerationRef.current;
    clearTimeout(rollingTimerRef.current);
    clearTimeout(resumeTimerRef.current);
    resumeTimerRef.current = setTimeout(() => {
      if (rollingGenerationRef.current !== generation) {
        return;
      }

      moveTo(activeIndexRef.current + 1);
      startRolling();
    }, 5000);
  };

  const handleDismissForToday = () => {
    if (!slug || activeItem?.id === undefined) {
      return;
    }

    if (!dismissAdItemForToday(window.localStorage, slug, activeItem.id, new Date())) {
      return;
    }

    clearTimeout(rollingTimerRef.current);
    clearTimeout(resumeTimerRef.current);
    rollingGenerationRef.current += 1;

    const nextVisibleItemCount = visibleItems.length - 1;
    const nextIndex = nextVisibleItemCount === 0 ? 0 : activeIndex % nextVisibleItemCount;
    activeIndexRef.current = nextIndex;
    setActiveIndex(nextIndex);
    setDismissalState((current) => ({
      dismissedItemIds: new Set([...current.dismissedItemIds, String(activeItem.id)]),
      slug,
    }));
  };

  if (!isVisible) {
    return null;
  }

  return (
    <S.Ad ref={adRef} className={className} $variant={variant} data-testid={`ad-${variant}`}>
      <S.Track
        data-testid={`ad-track-${variant}`}
        style={{ transform: `translateX(-${activeIndex * 100}%)` }}
      >
        {visibleItems.map((item, index) => {
          const isLinked = Boolean(item.href);

          const handleClick = () => {
            if (isLinked && item.id !== undefined) {
              trackCatalogEvent(String(item.title ?? ''));
            }
          };

          return (
            <S.Slide
              as={isLinked ? 'a' : 'div'}
              href={isLinked ? item.href : undefined}
              onClick={isLinked ? handleClick : undefined}
              rel={isLinked ? 'noopener noreferrer' : undefined}
              target={isLinked ? '_blank' : undefined}
              key={`${variant}-${index}`}
              $backgroundColor={item.backgroundColor}
              $textColor={item.textColor}
              $variant={variant}
            >
              {item.image && (variant.startsWith('banner') || variant.startsWith('card')) && (
                <S.Image
                  src={item.image.src}
                  alt={item.image.alt}
                  data-testid={`ad-image-${variant}`}
                  $variant={variant}
                />
              )}
              {!item.image && (
                <S.Content $variant={variant}>
                  <S.Title $variant={variant}>{item.title}</S.Title>
                  {item.body && <S.Body $variant={variant}>{item.body}</S.Body>}
                </S.Content>
              )}
            </S.Slide>
          );
        })}
      </S.Track>
      {hasControls && variant.startsWith('card') && (
        <S.CardCarouselNav data-testid={`ad-card-nav-${variant}`}>
          <S.CardArrowButton
            aria-label='이전 광고'
            type='button'
            onClick={() => handleManualMove(activeIndex - 1)}
          >
            <Icon name='chevron' size={20} color='white' direction='left' />
          </S.CardArrowButton>
          <S.CardArrowButton
            aria-label='다음 광고'
            type='button'
            onClick={() => handleManualMove(activeIndex + 1)}
          >
            <Icon name='chevron' size={20} color='white' direction='right' />
          </S.CardArrowButton>
        </S.CardCarouselNav>
      )}
      {hasBannerIndicators && (
        <S.IndicatorGroup
          ref={indicatorGroupRef}
          $variant={variant}
          data-testid={`ad-indicators-${variant}`}
        >
          {visibleItems.map((_, index) => {
            const isActive = index === activeIndex;

            return (
              <S.IndicatorButton
                aria-current={isActive ? 'true' : undefined}
                aria-label={`${index + 1}번째 광고`}
                key={`${variant}-indicator-${index}`}
                onClick={() => handleManualMove(index)}
                type='button'
                $active={isActive}
                $color={indicatorColor}
                $variant={variant}
              />
            );
          })}
        </S.IndicatorGroup>
      )}
      {hasTodayDismissButton && (
        <Tooltip label='오늘 하루 보지 않기' placement='top'>
          <S.CloseButton
            ref={closeButtonRef}
            aria-label='오늘 하루 보지 않기'
            onClick={handleDismissForToday}
            type='button'
          >
            <Icon name='cancelSmall' size={20} color={closeButtonColor} />
          </S.CloseButton>
        </Tooltip>
      )}
    </S.Ad>
  );
};

export default Ad;

