import { useRouter } from 'next/router';

import { render, screen } from '@testing-library/react';
import { act } from 'react-dom/test-utils';

import Ad from './Ad';
import { sendAdTrackingEvent } from './adTracking';
import { getImageIndicatorColor } from './getAdIndicatorColor';
import { useStrapiCatalog } from './useStrapiCatalog';

jest.mock('../Icon', () => ({
  Icon: ({ color, name }: { color?: string; name: string }) => (
    <span data-color={color} data-testid={`icon-${name}`} />
  ),
}));

jest.mock('../Tooltip', () => ({
  Tooltip: ({ children, label }: React.PropsWithChildren<{ label: string }>) => (
    <span data-tooltip-label={label}>{children}</span>
  ),
}));

jest.mock('./useStrapiCatalog');

jest.mock('next/router', () => ({
  useRouter: jest.fn(),
}));

jest.mock('./adTracking', () => ({
  sendAdTrackingEvent: jest.fn(() => true),
}));

jest.mock('./getAdIndicatorColor', () => ({
  ...jest.requireActual('./getAdIndicatorColor'),
  getImageIndicatorColor: jest.fn(),
}));

const mockedUseStrapiCatalog = jest.mocked(useStrapiCatalog);
const mockedUseRouter = jest.mocked(useRouter);
const mockedSendAdTrackingEvent = jest.mocked(sendAdTrackingEvent);
const mockedGetImageIndicatorColor = jest.mocked(getImageIndicatorColor);

describe('Ad', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.clearAllMocks();
    mockedGetImageIndicatorColor.mockResolvedValue('#333333');
    mockedUseRouter.mockReturnValue({ query: { storeName: 'sixshoptest01' } } as never);
    window.localStorage.clear();
  });

  afterEach(() => {
    jest.restoreAllMocks();
    jest.useRealTimers();
  });

  it('loads Catalog slides when slug is provided', () => {
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ title: 'Catalog title', body: 'Catalog body' }],
    } as never);

    render(<Ad slug='catalog-slug' variant='banner-large' />);

    expect(screen.getByText('Catalog title')).toBeTruthy();
    expect(screen.getByText('Catalog body')).toBeTruthy();
    expect(mockedUseStrapiCatalog).toHaveBeenCalledWith('catalog-slug');
  });

  it('tracks each Catalog creative impression once after the route store identity is ready', () => {
    mockedUseRouter.mockReturnValue({ query: {} } as never);
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ id: 3151, title: 'Catalog title' }],
    } as never);

    const { rerender } = render(<Ad slug='catalog-slug' variant='banner-small' />);

    expect(mockedSendAdTrackingEvent).not.toHaveBeenCalled();

    mockedUseRouter.mockReturnValue({ query: { storeName: 'sixshoptest01' } } as never);
    rerender(<Ad slug='catalog-slug' variant='banner-small' />);
    rerender(<Ad slug='catalog-slug' variant='banner-small' />);

    expect(mockedSendAdTrackingEvent).toHaveBeenCalledTimes(1);
    expect(mockedSendAdTrackingEvent).toHaveBeenCalledWith({
      event: 'catalog-slug',
      user: 'sixshoptest01',
      value: 'Catalog title',
    });
  });

  it('tracks the same Catalog creative again when the store identity changes', () => {
    mockedUseRouter.mockReturnValue({ query: { storeName: 'first-store' } } as never);
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [{ id: 3151, title: 'Catalog title' }],
    } as never);

    const { rerender } = render(<Ad slug='catalog-slug' variant='banner-small' />);

    mockedUseRouter.mockReturnValue({ query: { storeName: 'second-store' } } as never);
    rerender(<Ad slug='catalog-slug' variant='banner-small' />);

    expect(
      mockedSendAdTrackingEvent.mock.calls.filter(([event]) => event.event === 'catalog-slug')
    ).toEqual([
      [expect.objectContaining({ user: 'first-store' })],
      [expect.objectContaining({ user: 'second-store' })],
    ]);
  });

  it('tracks linked Catalog slide clicks but not indicator clicks', () => {
    window.localStorage.setItem(
      'user',
      JSON.stringify({ currentStore: { storeName: 'sixshoptest01' } })
    );
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [
        { href: 'https://example.com/1', id: 1, title: '첫 광고' },
        { href: 'https://example.com/2', id: 2, title: '두 번째 광고' },
      ],
    } as never);
    render(<Ad slug='catalog-slug' variant='banner-small' />);
    mockedSendAdTrackingEvent.mockClear();

    act(() => screen.getByRole('button', { name: '2번째 광고' }).click());

    expect(mockedSendAdTrackingEvent).toHaveBeenCalledTimes(1);

    act(() => screen.getByRole('link', { name: '두 번째 광고' }).click());

    expect(mockedSendAdTrackingEvent).toHaveBeenLastCalledWith({
      event: 'catalog-slug',
      user: 'sixshoptest01',
      value: '두 번째 광고',
    });
  });

  it('tracks each active Catalog creative impression only once', () => {
    window.localStorage.setItem(
      'user',
      JSON.stringify({ currentStore: { storeName: 'sixshoptest01' } })
    );
    mockedUseStrapiCatalog.mockReturnValue({
      isError: false,
      isLoading: false,
      items: [
        { id: 1, title: '첫 광고' },
        { id: 2, title: '두 번째 광고' },
      ],
    } as never);
    render(<Ad slug='catalog-slug' variant='banner-small' />);

    act(() => screen.getByRole('button', { name: '2번째 광고' }).click());
    act(() => screen.getByRole('button', { name: '1번째 광고' }).click());

    expect(
      mockedSendAdTrackingEvent.mock.calls.filter(([event]) => event.event === 'catalog-slug')
    ).toEqual([
      [
        expect.objectContaining({
          event: 'catalog-slug',
          user: 'sixshoptest01',
          value: '첫 광고',
        }),
      ],
      [
        expect.objectContaining({
          event: 'catalog-slug',
          user: 'sixshoptest01',
          value: '두 번째 광고',
        }),
      ],
    ]);
  });

  it.each([
    ['banner-small', '56px'],
    ['banner-large', '80px'],
    ['banner-landing', '50px'],
    ['card-large', '200px'],
    ['card-medium', '170px'],
    ['card-small', '160px'],
  ] as const)('renders the %s variant with the Figma height', (variant, height) => {
    render(<Ad variant={variant} items={[{ title: 'title', body: 'body' }]} />);

    const ad = screen.getByTestId(`ad-${variant}`);

    expect(getComputedStyle(ad).height).toBe(height);
    expect(ad.textContent).toContain('title');
    expect(ad.textContent).toContain('body');
  });

  it('centers a banner image and crops its horizontal overflow', () => {
    render(
      <Ad
        variant='banner-large'
        items={[
          { title: 'title', body: 'body', image: { alt: '광고 이미지', src: '/banner.png' } },
        ]}
      />
    );

    const ad = screen.getByTestId('ad-banner-large');
    const image = screen.getByRole('img', { name: '광고 이미지' });
    const slide = screen.getByTestId('ad-track-banner-large').firstElementChild;

    expect(getComputedStyle(ad).overflow).toBe('hidden');
    expect(slide && getComputedStyle(slide).padding).toBe('');
    expect(screen.queryByText('title')).toBeNull();
    expect(screen.queryByText('body')).toBeNull();
    expect(getComputedStyle(image).position).toBe('absolute');
    expect(getComputedStyle(image).left).toBe('50%');
    expect(getComputedStyle(image).width).toBe('auto');
    expect(getComputedStyle(image).transform).toBe('translateX(-50%)');
  });

  it.each(['card-large', 'card-medium', 'card-small'] as const)(
    'renders the %s card as a linked bordered area',
    (variant) => {
      render(<Ad variant={variant} items={[{ title: 'title', href: '/landing' }]} />);

      const ad = screen.getByTestId(`ad-${variant}`);
      const link = screen.getByRole('link', { name: 'title' });

      expect(link.getAttribute('href')).toBe('/landing');
      expect(link.getAttribute('target')).toBe('_blank');
      expect(link.getAttribute('rel')).toBe('noopener noreferrer');
      expect(getComputedStyle(ad).border).toBe('');
      expect(getComputedStyle(ad).boxShadow).toBe('inset 0 0 0 1px rgba(0,0,0,0.2)');
      expect(getComputedStyle(ad).borderRadius).toBe('12px');
      expect(getComputedStyle(link).border).toBe('');
    }
  );

  it('renders a card image without card text content', () => {
    render(
      <Ad
        variant='card-large'
        items={[{ title: 'title', body: 'body', image: { alt: '카드 이미지', src: '/card.png' } }]}
      />
    );

    const image = screen.getByRole('img', { name: '카드 이미지' });

    expect(getComputedStyle(image).width).toBe('100%');
    expect(getComputedStyle(image).height).toBe('100%');
    expect(getComputedStyle(image).objectFit).toBe('cover');
    expect(screen.queryByText('title')).toBeNull();
    expect(screen.queryByText('body')).toBeNull();
  });

  it('uses the card-specific title and summary content area', () => {
    render(<Ad variant='card-large' items={[{ title: 'title', body: 'summary' }]} />);

    const content = screen.getByText('title').parentElement;
    const body = screen.getByText('summary');

    expect(content && getComputedStyle(content).padding).toBe('20px');
    expect(content && getComputedStyle(content).height).toBe('100%');
    expect(content && getComputedStyle(content).textAlign).toBe('left');
    expect(getComputedStyle(body).fontSize).toBe('14px');
    expect(getComputedStyle(body).lineHeight).toBe('1.5');
  });

  it('renders card slides with the Figma carousel navigation pill', () => {
    render(<Ad variant='card-large' items={[{ title: '첫 카드' }, { title: '두 번째 카드' }]} />);

    expect(getComputedStyle(screen.getByTestId('ad-card-large')).position).toBe('relative');
    expect(screen.queryByTestId('ad-card-nav-card-large')).not.toBeNull();
    expect(screen.queryByRole('button', { name: '이전 광고' })).not.toBeNull();
    expect(screen.queryByRole('button', { name: '다음 광고' })).not.toBeNull();
  });

  it('moves card slides with the card carousel arrows', () => {
    render(<Ad variant='card-large' items={[{ title: '첫 카드' }, { title: '두 번째 카드' }]} />);

    const track = screen.getByTestId('ad-track-card-large');
    expect(track.getAttribute('style')).toContain('translateX(-0%)');

    act(() => {
      screen.getByRole('button', { name: '다음 광고' }).click();
    });

    expect(track.getAttribute('style')).toContain('translateX(-100%)');
  });

  it('opens a linked banner slide in a new tab', () => {
    render(
      <Ad
        variant='banner-large'
        items={[
          {
            title: 'title',
            href: 'https://example.com',
            image: { alt: 'image', src: '/image.png' },
          },
        ]}
      />
    );

    const link = screen.getByRole('link');

    expect(link.getAttribute('target')).toBe('_blank');
    expect(link.getAttribute('rel')).toBe('noopener noreferrer');
  });

  it('renders every item in the slide track', () => {
    render(
      <Ad
        variant='banner-large'
        items={[
          { title: '첫 번째', body: '첫 본문' },
          { title: '두 번째', body: '두 본문' },
        ]}
      />
    );

    expect(screen.getByText('첫 번째')).toBeTruthy();
    expect(screen.getByText('두 번째')).toBeTruthy();
    expect(screen.getByTestId('ad-track-banner-large').children).toHaveLength(2);
  });

  it.each([
    ['banner-small', '28px'],
    ['banner-large', '32px'],
    ['banner-landing', '28px'],
  ] as const)('renders clickable Figma indicators for up to 20 %s items', (variant, height) => {
    render(
      <Ad
        variant={variant}
        items={Array.from({ length: 20 }, (_, index) => ({ title: `${index + 1}번째` }))}
      />
    );

    const indicators = screen.getAllByRole('button', { name: /번째 광고/ });
    const indicatorGroup = screen.getByTestId(`ad-indicators-${variant}`);
