  });

  it.each([
    ['banner-small', '28px'],
    ['banner-large', '32px'],
    ['banner-landing', '28px'],
  ] as const)('renders clickable Figma indicators for up to 20 %s items', (variant, height) => {
    render(
      <Ad
        variant={variant}
        items={Array.from({ length: 20 }, (_, index) => ({ title: `${index + 1}번째` }))}
      />
