  it('uses the active image brightness color for banner indicators', async () => {
    mockedGetImageIndicatorColor.mockResolvedValue('#ffffff');

    render(
      <Ad
        variant='banner-large'
        items={[
          { title: '첫 번째', image: { alt: '첫 번째', src: '/dark.png' } },
